fn is_ascii_digit(c: char) -> bool {
    // Check if the character is in the range of ASCII digits '0' to '9'
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // Check if all characters in the string are ASCII digits
    for c in s.chars() {
        if !is_ascii_digit(c) {
            return false; // Return false immediately if a non-digit is found
        }
    }
    true // All characters are digits, including the case for empty string
}